  "黑色": "<rect width=\"240\" height=\"180\" rx=\"24\" fill=\"#f8fafc\" stroke=\"#e2e8f0\" stroke-width=\"3\"/>\n  <rect x=\"22\" y=\"18\" width=\"196\" height=\"144\" rx=\"16\" fill=\"#18181b\"/>"
