for (const [name, inner] of Object.entries(ICONS)) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 180">\n  ${inner}\n</svg>\n`;
  await writeFile(resolve(root, `${name}.svg`), svg, 'utf8');
}
console.log(`Successfully synced ${Object.keys(ICONS).length} SVG assets!`);
